"""R154 round 3, D2 (final driver): coarse LP grid + cuts generated by the
Lipschitz branch-and-bound itself.

The B&B that certifies the certificate is also the best cut generator: the
intervals it cannot discard are exactly the places where f dips towards c.
So the LP is kept small (grid 0.02) and each round adds the B&B survivors.
"""
import math, pickle, sys, time, numpy as np
from cert3 import base, g0h, g1h, vdict, fval, m, lip
from close3 import lp
from close4 import resonance_grid


def survivors(T, us, a, b0, b1, v, taumax, target, w0=0.02, wmin=5e-8, cap=40000):
    """Adaptive Lipschitz refinement.  Returns (certified_lower_bound_flag,
    best midpoint value, list of surviving midpoints)."""
    L = lip(T, us, a, b0, b1, v)
    n0 = int(math.ceil(taumax/w0)); w = taumax/n0
    cur = np.arange(n0)*w
    best = np.inf
    while True:
        mid = cur + w/2
        vals = np.empty(len(mid))
        for i in range(0, len(mid), 200000):
            sl = slice(i, i+200000); vals[sl] = fval(mid[sl], T, us, a, b0, b1, v)
        best = min(best, float(vals.min()))
        keep = vals - L*w/2 < target
        nk = int(keep.sum())
        if nk == 0:
            return True, best, np.array([]), L
        if w/2 < wmin:
            return False, best, mid[keep][np.argsort(vals[keep])][:cap], L
        idx = np.where(keep)[0]
        if len(idx) > 400000:
            idx = idx[np.argsort(vals[idx])][:400000]
        cur = np.repeat(cur[idx], 2) + np.tile(np.array([0.0, w/2]), len(idx))
        w = w/2


def run(T, M, U, taumax, rounds=14, dtau=0.02, dper=0.02, tag='', qmax=10, rhomax=None):
    v = vdict(T)
    d = 2*T/M; J = int((2*T+U)/d); us = np.arange(M, J+1)*d; P = 2*math.pi/d
    tau = np.unique(np.concatenate([np.arange(1e-7, taumax, dtau),
                                    resonance_grid(P, taumax, qmax, 0.01, 1e-3)]))
    tp = np.unique(np.concatenate([np.arange(0.0, P, dper),
                                   resonance_grid(P, P, qmax, 0.01, 1e-3)]))
    tpf = np.arange(0.0, P, 2e-5)
    print(f"  [{tag}] atoms={len(us)} P={P:.3f} rows0={len(tau)}/{len(tp)}", flush=True)
    best = None
    for it in range(rounds):
        t0 = time.time()
        sol = lp(T, us, tau, tp, P, taumax, v, rhomax=rhomax)
        if sol is None: print("  LP fail"); return best
        a, b0, b1 = sol['a'], sol['b0'], sol['b1']
        ok, bb, surv, L = survivors(T, us, a, b0, b1, v, taumax, sol['c']-1e-10)
        nuf = np.empty(len(tpf))
        for i in range(0, len(tpf), 20000):
            sl = slice(i, i+20000); nuf[sl] = 2*(np.cos(np.outer(tpf[sl], us)) @ a)
        Ln = 2*float(np.sum(np.abs(a)*us))
        rho = -(float(nuf.min()) - Ln*2e-5/2)
        k0 = 2*math.cosh(T)/taumax + math.sinh(T)/taumax**2
        k1 = 8*T*math.sinh(T)/taumax
        tail = m(np.array([taumax]))[0] - sum(v.values()) - rho - abs(b0)*k0 - abs(b1)*k1
        cert = min(tail, bb) if ok or bb <= sol['c'] else min(tail, bb)
        print(f"  [{tag}] it{it} LPc={sol['c']:.6e} bbmin={bb:.6e} nsurv={len(surv)} "
              f"rho={rho:.4f} tail={tail:.6e} L={L:.0f} CERT={cert:.6e} "
              f"b0={b0:.6f} b1={b1:.6f} |a|1={np.abs(a).sum():.2f} ({time.time()-t0:.0f}s)", flush=True)
        rec = dict(T=T, M=M, U=U, d=d, us=us, a=a, b0=b0, b1=b1, rho=rho, tail=tail,
                   lp=sol['c'], bb=bb, cert=cert, taumax=taumax, P=P, v=v, L=L)
        if best is None or cert > best['cert']: best = rec
        nvp = np.where(nuf < -sol['rho'] - 1e-11)[0]
        if len(surv) == 0 and len(nvp) == 0:
            print("  converged", flush=True); break
        if len(surv): tau = np.unique(np.concatenate([tau, surv]))
        if len(nvp):
            srt = nvp[np.argsort(nuf[nvp])][:3000]
            tp = np.unique(np.concatenate([tp, tpf[srt]]))
    return best


if __name__ == '__main__':
    M = int(sys.argv[1]); U = float(sys.argv[2])
    which = sys.argv[3] if len(sys.argv) > 3 else 'log3'
    tmax = float(sys.argv[4]) if len(sys.argv) > 4 else 400.0
    T = 0.5*math.log(3) if which == 'log3' else math.log(2)
    rmx = float(sys.argv[5]) if len(sys.argv) > 5 else None
    dt = float(sys.argv[6]) if len(sys.argv) > 6 else 0.02
    r = run(T, M, U, tmax, dtau=dt, rhomax=rmx, tag=f'{which}M{M}U{U:g}t{tmax:g}r{rmx}')
    if r: pickle.dump(r, open(f'c5_{which}_M{M}_t{int(tmax)}.pkl', 'wb'))
